import java.io.*;
import java.util.Arrays;

public class Main {

    private static byte[] data;
    private static int pos;

    private static int readInt() {
        while (pos < data.length && (data[pos] < '0' || data[pos] > '9')) pos++;
        int x = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') {
            x = x * 10 + (data[pos++] - '0');
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        data = readAll(System.in);
        pos = 0;

        int N = readInt();
        int M = readInt();

        int[] ea = new int[M], eb = new int[M], deg = new int[N];
        for (int i = 0; i < M; i++) {
            int a = readInt() - 1;
            int b = readInt() - 1;
            ea[i] = a; eb[i] = b;
            deg[a]++; deg[b]++;
        }

        int[] start = new int[N + 1];
        for (int i = 0; i < N; i++) start[i + 1] = start[i] + deg[i];

        int total = 2 * M;
        int[] adjV = new int[total], adjS = new int[total];
        int[] fill = new int[N];
        for (int i = 0; i < M; i++) {
            int a = ea[i], b = eb[i];
            int t = start[b] + fill[b]++;
            adjV[t] = a; adjS[t] = i << 1;       // estado F(a,b): em a, vindo de b
            t = start[a] + fill[a]++;
            adjV[t] = b; adjS[t] = (i << 1) | 1; // estado F(b,a): em b, vindo de a
        }
        ea = null; eb = null; fill = null;

        // ordena cada lista de adjacência por valor do vizinho (decrescente)
        long[] pack = new long[total];
        for (int u = 0; u < N; u++) {
            int s = start[u], e = start[u + 1], len = e - s;
            if (len <= 1) continue;
            for (int i = s; i < e; i++)
                pack[i - s] = ((long) adjV[i] << 32) | (adjS[i] & 0xffffffffL);
            Arrays.sort(pack, 0, len);
            for (int i = 0; i < len; i++) {
                long v = pack[len - 1 - i];
                adjV[s + i] = (int) (v >>> 32);
                adjS[s + i] = (int) v;
            }
        }
        pack = null;

        // f[s] = F(x,y): maior nº de vértices do sufixo estando em x, tendo vindo de y
        // F(x,y) = 1 + max{ F(v,x) : v vizinho de x com v > y }
        int[] f = new int[total];
        int[] ptr = new int[N];
        System.arraycopy(start, 0, ptr, 0, N);
        int[] msf = new int[N];

        // processa grupos por m = min(x,y), decrescente (ordem topológica do DAG de estados)
        for (int m = N - 1; m >= 0; m--) {
            int s = start[m], e = start[m + 1];
            int pe = s;
            while (pe < e && adjV[pe] > m) pe++;
            if (pe == s) continue;

            // passo B: estados F(u, m) com u > m (dependem só de grupos > m)
            for (int i = s; i < pe; i++) {
                int u = adjV[i];
                int p = ptr[u], qe = start[u + 1], best = msf[u];
                while (p < qe && adjV[p] > m) {
                    int val = f[adjS[p]];
                    if (val > best) best = val;
                    p++;
                }
                ptr[u] = p; msf[u] = best;
                f[adjS[i]] = best + 1;
            }

            // passo A: estados F(m, w) com w > m, em ordem decrescente de w
            // (usam F(v, m) dos estados do passo B deste grupo)
            int p = ptr[m], qe = start[m + 1], best = msf[m];
            for (int i = s; i < pe; i++) {
                int w = adjV[i];
                while (p < qe && adjV[p] > w) {
                    int val = f[adjS[p]];
                    if (val > best) best = val;
                    p++;
                }
                f[adjS[i] ^ 1] = best + 1;
            }
            ptr[m] = p; msf[m] = best;
        }

        // resposta: R(c) = 1 + max_{v vizinho de c} F(v, c)
        StringBuilder sb = new StringBuilder(Math.max(N * 7, 16));
        for (int c = 0; c < N; c++) {
            int best = 0;
            for (int i = start[c], e = start[c + 1]; i < e; i++) {
                int val = f[adjS[i]];
                if (val > best) best = val;
            }
            if (c > 0) sb.append(' ');
            sb.append(best + 1);
        }
        System.out.println(sb);
    }

    private static byte[] readAll(InputStream is) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream(1 << 23);
        byte[] chunk = new byte[1 << 16];
        for (int r; (r = is.read(chunk)) > 0; ) {
            bos.write(chunk, 0, r);
        }
        return bos.toByteArray();
    }
}
